<script setup>
import { Head, router } from '@inertiajs/vue3'; import { reactive } from 'vue'; import AppLayout from '../../../Layouts/AppLayout.vue';
const props=defineProps({logs:Object,filters:Object,actors:Array,actions:Array,types:Array}); const form=reactive({actor:props.filters.actor||'',action:props.filters.action||'',type:props.filters.type||'',from:props.filters.from||'',to:props.filters.to||'',search:props.filters.search||''}); const submit=()=>router.get('/admin/audit-logs',form,{preserveState:true,replace:true});
const labels={'user.created':'ایجاد کاربر','user.updated':'ویرایش کاربر','user.role_changed':'تغییر نقش','course.created':'ایجاد دوره','course.updated':'ویرایش دوره','course.archived':'بایگانی دوره','lesson.archived':'بایگانی درس','video.archived':'بایگانی ویدئو','video.publication_changed':'تغییر انتشار ویدئو','session.revoked_by_admin':'لغو نشست توسط مدیر'};
</script>
<template><AppLayout><Head title="گزارش رویدادها"/><section class="rounded-2xl border bg-white p-5"><h1 class="mb-4 text-xl font-bold">گزارش رویدادها</h1><form class="grid gap-3 md:grid-cols-3" @submit.prevent="submit"><select v-model="form.actor"><option value="">همه کاربران</option><option v-for="a in actors" :key="a.id" :value="a.id">{{a.first_name}} {{a.last_name}}</option></select><select v-model="form.action"><option value="">همه رویدادها</option><option v-for="a in actions" :key="a" :value="a">{{labels[a]||a}}</option></select><select v-model="form.type"><option value="">همه موجودیت‌ها</option><option v-for="t in types" :key="t" :value="t">{{t.split('\\').pop()}}</option></select><input v-model="form.from" type="date"><input v-model="form.to" type="date"><input v-model="form.search" placeholder="جستجو در توضیح"><button class="rounded-xl bg-teal-700 px-4 py-2 text-white">اعمال فیلتر</button></form><div class="mt-5 space-y-2"><article v-for="log in logs.data" :key="log.id" class="rounded-xl border p-3"><div class="flex flex-wrap justify-between gap-2"><strong>{{labels[log.action]||log.action}}</strong><time class="text-xs text-slate-500">{{new Date(log.created_at).toLocaleString('fa-IR')}}</time></div><p class="text-sm text-slate-600">عامل: {{log.actor?`${log.actor.first_name} ${log.actor.last_name}`:'سیستم'}} · {{log.auditable_type?.split('\\').pop()||'عمومی'}} #{{log.auditable_id||'—'}}</p><details v-if="log.metadata&&Object.keys(log.metadata).length" class="mt-2 text-sm"><summary class="cursor-pointer text-teal-700">جزئیات امن</summary><div v-for="(value,key) in log.metadata" :key="key"><b>{{key}}:</b> {{typeof value==='object'?JSON.stringify(value):value}}</div></details></article><p v-if="!logs.data.length" class="py-8 text-center text-slate-500">هنوز رویدادی ثبت نشده است.</p></div></section></AppLayout></template>
